diff --git a/t/baseline-parser-lib.t b/t/baseline-parser-lib.t
index a5d45470c5..106e2793d2 100644
--- a/t/baseline-parser-lib.t
+++ b/t/baseline-parser-lib.t
@@ -68,8 +68,11 @@ foreach my $file (@pm_files) {
             pass "$rel_path parsed successfully";
             $passed++;
         } else {
-            # Track failure but don't fail the test - this is a baseline assessment
-            pass "$rel_path failed to parse (baseline)";
+            # Known issue: perl.bnf has limitations with complex parameter lists
+            # See phase6-results.md for details
+            todo "perl.bnf grammar has known limitations with complex method parameter lists" => sub {
+                fail "$rel_path failed to parse";
+            };
             $failed++;
             push @failures, $rel_path;
         }
diff --git a/t/baseline-parser-t.t b/t/baseline-parser-t.t
index b149aa8e9d..d17b3ca564 100644
--- a/t/baseline-parser-t.t
+++ b/t/baseline-parser-t.t
@@ -73,8 +73,11 @@ foreach my $file (@t_files) {
             pass "$rel_path parsed successfully";
             $passed++;
         } else {
-            # Track failure but don't fail the test - this is a baseline assessment
-            pass "$rel_path failed to parse (baseline)";
+            # Known issue: perl.bnf has limitations with complex syntax
+            # Some test files use advanced features not yet in grammar
+            todo "perl.bnf grammar has known limitations - test files may use advanced syntax" => sub {
+                fail "$rel_path failed to parse";
+            };
             $failed++;
             push @failures, $rel_path;
         }

